//synth-c library
//

//some global regs
#define $dt reg10
#define $b  reg06
#define $b2 reg07
#define $resize reg13
#define rand1() ((rand(1000)-2000)/1000)
//mb=megabuf; gmb=gmegabuf
#define mb(a) megabuf(a)
#define gmb(a) gmegabuf(a)
//some combinations of expressions i use a lot
#define rand2() (rand(2000)-1000)*.001 /*random number between -1 and 1*/   
#define asinsin(a) asin(sin(a)) /*asin(sin(bla)) good for looping a texture*/
#define dist(x,y,z) sqrt(x*x+y*y+z*z)
#define idist(x,y,z) invsqrt(x*x+y*y+z*z)
//loop with offset and counter for buffers  
#define offloop(off,a,b) lc=off; loop(a,b;lc=lc+1);lc=0;
//value shifts 
#define vshift(a,b,c) spd=pow(c,100*reg10); ispd=1-spd;a=a*spd+b*ispd; 
#define lshift(a,b,c) diff=abs(a-b); spd=min(reg10*c,diff); a=if(below(diff,spd),a, a-spd*below(b,a)+spd*above(b,a)); 


//global registers 
#define initregs() p=$pi;p2=$pi*2;p3=$pi*3;sq2=sqrt(2);isq2=1/sqrt(2);ip=1/$pi; /*common variables*/
#define loadsscregs() ox=reg50;rx=reg51;xc=reg52;xs=reg53;oy=reg56;ry=reg57;yc=reg58;ys=reg59;oz=reg62;rz=reg63;zc=reg64;zs=reg65; /*for superscope rotation*/
#define loaddmregs()  ox=reg50;rx=reg51;xcdm=reg54;xsdm=reg55;oy=reg56;ry=reg57;ycdm=reg60;ysdm=reg61;oz=reg62;rz=reg63;zcdm=reg66;zsdm=reg67; /*for inverse/raytracing/dm rotation*/
#define loadsndregs() osc=reg00;spec=reg01;avgsnd=reg02;osctot=reg03;spectot=reg04;avgtot=reg05; beat=reg06;b2=reg07; /*sound value globals*/
#define loadszregs() resize=reg13;aspx=reg14;aspy=reg15;scsz=reg16;iaspx=1/aspx;iaspy=1/aspy; /*screen size globals, for resize, aspect ratio etc*/
//create object rotation sines
#define objrotsines(orx,ory,orz) xso=sin(orx);xco=cos(orx);yso=sin(ory);yco=cos(ory);zso=sin(orz);zco=cos(orz); /*create sines for object-space rotation*/
//3d rotation, tranformation and projection (requires loadsccregs() 
#define move(x1,y1,z1) x1=x1-ox;y1=y1-oy;z1=z1-oz;  /*movemove camera*/
#define objrotyxz(x1,y1,z1) x2=z1*yso+x1*yco;z2=z1*yco-x1*yso;y2=y1*xco-z2*xso;zb1=y1*xso+z2*xco;xb1=x2*zco-y2*zso;yb1=y2*zco+x2*zso;x1=xb1;y1=yb1;z1=zb1;
#define rotateyxz(x1,y1,z1) x2=z1*ys+x1*yc;z2=z1*yc-x1*ys;y2=y1*xc-z2*xs;z3=y1*xs+z2*xc; x3=x2*zc-y2*zs;y3=y2*zc+x2*zs;
#define project(x3,y3,z3) draw=above(z3,.025);z4=if(draw,1/z3,100);x=x3*z4*aspx;y=y3*z4*aspy;
//dm rotation (for raytracing) (requires loaddmregs() )
#define rotatezxy(x1,y1,z1) x2=x1*zcdm+y1*zsdm;y2=x1*zsdm-y1*zcdm; y3=y2*xcdm+z1*xsdm;z2=y2*xsdm-z1*xcdm; x3=z2*ysdm-x2*ycdm;z3=z2*ycdm+x2*ysdm;
#define raytransform(x3,y3,z3) ix=(x3*k)-ox;iy=(y3*k)-oy;iz=(z3*k)-oz;

//
/*#define ppinit(points,offset) ipoints=1/points; offloop(offset, points, mb(lc */

//per point case (=string of if statements) (for defining shape per point, supports 5 points)
#define ppcase5(a,b,c,d,e) if(equal(ppc,0),a,if(equal(ppc,1),b,if(equal(ppc,2),c,if(equal(ppc,3),d,e))))

// solvers, abc-formula for a*sqr(x)+b*x+c=0
#define solve(a,b,c) di=sqr(b)-a*c;di=if(below(di,0),0,sqrt(di));s1=(-b+di)/a;s2=(-b-di)/a;

