red0=.3;blue0=0;green0=.3;
hslred=(min(max(abs(asin(cos(-hue)))*scp-1,0),1)*sat+adsat)*mlum+adlum;hslgreen=(min(max(abs(asin(cos(-hue+pf3)))*scp-1,0),1)*sat+adsat)*mlum+adlum;hslblue=(min(max(abs(asin(cos(-hue-pf3)))*scp-1,0),1)*sat+adsat)*mlum+adlum;
red=if(hslrgb,red0,hslred);green=if(hslrgb,green0,hslgreen);blue=if(hslrgb,blue0,hslblue);
reg20=red;reg21=green;reg22=blue;
//3d rotation
bca=(bca+beat)%8;revt=if(rev,0,revt+dt);rev=equal(bca,0)*above(revt,4); 
rdir=if(rev,-rdir,rdir);
cammov0=(.2+osc*3+spec*3+b2)*dt*.7*rdir;
lshift(cammov,cammov0,.6);
ii=ii+cammov;i=ii;r=i*p2;

lshift(b3,bb,3);
d=1.3-spec-osc-b3*.05;
r=ii;
ox=sin(r)*d;
oy=sin(cos(t*.3)+t*.4)*.5;
oz=cos(r)*d;
zz=zz+(osc+bb*.1)*dt*rdir*2;

constdis=0;cd=constdist;projdist=1;ot=projdist*invsqrt(ox*ox+oy*oy+oz*oz);
ox=if(cd,ox*ot,ox); oy=if(cd,oy*ot,oy); oz=if(cd,oz*ot,oz); 
//ssc

ry=-atan2(ox,-oz);rx=atan2(oy,sqrt(ox*ox+oz*oz));rz=zz;
xs=-sin(rx);xc=cos(rx);ys=-sin(ry);yc=cos(ry);zs=-sin(rz);zc=cos(rz);
//dm
ry=-atan2(ox,-oz);rx=atan2(oy,sqrt(ox*ox+oz*oz));rz=-zz;
xsdm=sin(rx);xcdm=cos(rx);ysdm=sin(ry);ycdm=cos(ry);zsdm=sin(rz);zcdm=cos(rz);
//to global regs
